3. /// <summary>
4. /// Broadcasts reaction count updates to all subscribed Blazor Server circuits.
5. /// Each circuit subscribes on component mount and unsubscribes on dispose.
6. /// </summary>
7. public interface IReactionNotifier
8. {
9.     void Subscribe(Func<DateOnly, IReadOnlyDictionary<string, int>, Task> handler);
10.     void Unsubscribe(Func<DateOnly, IReadOnlyDictionary<string, int>, Task> handler);
11.     Task NotifyAsync(DateOnly date, IReadOnlyDictionary<string, int> counts);
12. }
13. 
14. /// <summary>
15. /// Thread-safe singleton implementation using an explicit subscriber list with Task.WhenAll fan-out.
16. /// Uses a Lock (System.Threading.Lock, .NET 9+) and snapshot-before-notify to avoid holding
17. /// the lock across async boundaries. Safe for concurrent subscribe/unsubscribe across circuits.
18. /// </summary>
19. public sealed class ReactionNotifier : IReactionNotifier
20. {
21.     private readonly List<Func<DateOnly, IReadOnlyDictionary<string, int>, Task>> _subscribers = [];
22.     private readonly Lock _lock = new();
23. 
24.     public void Subscribe(Func<DateOnly, IReadOnlyDictionary<string, int>, Task> handler)
25.     {
26.         lock (_lock) _subscribers.Add(handler);
27.     }
28. 
29.     public void Unsubscribe(Func<DateOnly, IReadOnlyDictionary<string, int>, Task> handler)
30.     {
31.         lock (_lock) _subscribers.Remove(handler);
32.     }
33. 
34.     public async Task NotifyAsync(DateOnly date, IReadOnlyDictionary<string, int> counts)
35.     {
36.         List<Func<DateOnly, IReadOnlyDictionary<string, int>, Task>> snapshot;
37.         lock (_lock) snapshot = [.._subscribers];
38.         await Task.WhenAll(snapshot.Select(h => h(date, counts)));
39.     }
40. }
