5. namespace aspire1.WeatherService.Services;
6. 
7. public class CachedWeatherService
8. {
9.     private readonly IDistributedCache _cache;
10.     private readonly ILogger<CachedWeatherService> _logger;
11.     private const string CacheKeyPrefix = "api:weather:forecast";
12. 
13.     public CachedWeatherService(IDistributedCache cache, ILogger<CachedWeatherService> logger)
14.     {
15.         _cache = cache;
16.         _logger = logger;
17.     }
18. 
19.     public async Task<WeatherForecast[]> GetWeatherForecastAsync(
20.         int maxItems = 10,
21.         CancellationToken cancellationToken = [REDACTED]     {
23.         var cacheKey = $"{CacheKeyPrefix}:{maxItems}";
24. 
25.         try
26.         {
27.             // Try cache first
28.             var cachedData = await _cache.GetStringAsync(cacheKey, cancellationToken);
29.             if (cachedData != null)
30.             {
31.                 _logger.LogInformation("Cache HIT for weather forecast (maxItems={MaxItems})", maxItems);
32.                 ApplicationMetrics.CacheHits.Add(1,
33.                     new KeyValuePair<string, object?>("entity", "weather"));
34.                 return JsonSerializer.Deserialize<WeatherForecast[]>(cachedData)!;
35.             }
36. 
37.             _logger.LogInformation("Cache MISS for weather forecast (maxItems={MaxItems})", maxItems);
38.             ApplicationMetrics.CacheMisses.Add(1,
39.                 new KeyValuePair<string, object?>("entity", "weather"));
40.         }
41.         catch (Exception ex)
42.         {
43.             _logger.LogWarning(ex, "Cache read failed, falling back to generation");
44.         }
45. 
46.         // Generate fresh data
47.         var forecasts = GenerateForecasts(maxItems);
48. 
49.         try
50.         {
51.             // Store in cache with 5-minute TTL
52.             var options = new DistributedCacheEntryOptions
53.             {
54.                 AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(5)
55.             };
56.             await _cache.SetStringAsync(
57.                 cacheKey,
58.                 JsonSerializer.Serialize(forecasts),
59.                 options,
60.                 cancellationToken);
61. 
62.             _logger.LogInformation("Cached weather forecast for 5 minutes");
63.         }
64.         catch (Exception ex)
